<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>New Transfer</title><style>body{font:15px Arial;background:#f4f6fa;color:#1b2940}.wrap{max-width:1000px;margin:30px auto}.card{background:white;padding:22px;border-radius:12px;margin:15px 0}input,select{padding:10px;margin:5px;border:1px solid #ccd5df;border-radius:6px;max-width:100%}button,a{background:#173d65;color:white;padding:10px 14px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}.line{display:flex;gap:6px;flex-wrap:wrap}.line select{flex:2;min-width:250px}.line input{width:130px}</style></head><body><main class="wrap"><h1>Request Stock Transfer</h1><p><a href="{{ route('transfers.index') }}">Back to Transfers</a></p>@foreach($errors->all() as $e)<p style="color:#b42318">{{ $e }}</p>@endforeach<form method="POST" action="{{ route('transfers.store') }}">@csrf<div class="card"><select name="from_branch_id" required><option value="">Source branch</option>@foreach($sourceBranches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select><select name="to_branch_id" required><option value="">Destination branch</option>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select><input name="notes" placeholder="Notes"></div><div class="card"><h2>Items</h2><div id="items"><div class="line"><select name="items[0][product_variant_id]" required><option value="">Product / SKU</option>@foreach($variants as $v)<option value="{{ $v->id }}">{{ $v->product->name }} — {{ $v->size }}/{{ $v->color }} ({{ $v->sku }})</option>@endforeach</select><input type="number" name="items[0][quantity]" min="1" value="1" required placeholder="Quantity"></div></div><button type="button" onclick="addItem()">+ Add item</button> <button>Create Transfer Request</button><p>Stock is deducted on source approval and added to the destination after receipt.</p></div></form></main><script>let row=1;function addItem(){let c=document.querySelector('#items .line').cloneNode(true);c.querySelectorAll('select,input').forEach(e=>{e.name=e.name.replace(/items\[0\]/,'items['+row+']');if(e.tagName==='SELECT')e.selectedIndex=0;else e.value='1'});document.getElementById('items').appendChild(c);row++}</script></body></html>